import 'package:flutter/material.dart';import '../services/app_state.dart';import '../models/study_models.dart';import '../widgets/app_header.dart';import '../widgets/section_title.dart';
class SubjectsPage extends StatelessWidget{const SubjectsPage({super.key});@override Widget build(BuildContext c)=>AnimatedBuilder(animation:AppState.instance,builder:(_,__) {final s=AppState.instance;return ListView(padding:const EdgeInsets.all(18),children:[const AppHeader(title:'المواد والدروس',subtitle:'سجّل ما أخذته في كل درس ليُبنى عليه الاختبار والمراجعة'),const SizedBox(height:18),SectionTitle('موادك',action:'إضافة',onTap:()=>_addSubject(c)),...s.subjects.map((x)=>Card(child:ExpansionTile(title:Text(x.name,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text('${x.lessons.length} دروس • ${(x.progress*100).round()}% مكتمل'),leading:CircularProgressIndicator(value:x.progress),children:[...x.lessons.map((l)=>CheckboxListTile(value:l.studied,onChanged:(_)=>s.toggleLesson(x,l),title:Text(l.title),subtitle:Text(l.learnedContent.isEmpty?'لم تسجل ما أخذته بعد':l.learnedContent,maxLines:2,overflow:TextOverflow.ellipsis),secondary:IconButton(icon:const Icon(Icons.edit_note),onPressed:()=>_edit(c,l))),ListTile(leading:const Icon(Icons.add_circle_outline),title:const Text('إضافة درس'),onTap:()=>_addLesson(c,x),),ListTile(leading:const Icon(Icons.delete_outline),title:const Text('حذف المادة'),onTap:(){s.deleteSubject(x);})])))]);});}
void _addSubject(BuildContext c){final x=TextEditingController();showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('إضافة مادة'),content:TextField(controller:x,decoration:const InputDecoration(labelText:'اسم المادة')),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('إلغاء')),FilledButton(onPressed:(){if(x.text.trim().isNotEmpty)AppState.instance.addSubject(x.text.trim());Navigator.pop(c);},child:const Text('حفظ'))]));}
void _addLesson(BuildContext c,Subject s){final x=TextEditingController();showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('إضافة درس'),content:TextField(controller:x,decoration:const InputDecoration(labelText:'اسم الدرس')),actions:[FilledButton(onPressed:(){if(x.text.trim().isNotEmpty)AppState.instance.addLesson(s,x.text.trim());Navigator.pop(c);},child:const Text('إضافة'))]));}
void _edit(BuildContext c,Lesson l){final x=TextEditingController(text:l.learnedContent);showDialog(context:c,builder:(_)=>AlertDialog(title:Text('ماذا أخذت في ${l.title}؟'),content:TextField(controller:x,maxLines:7,decoration:const InputDecoration(hintText:'اكتب القواعد والأفكار والنقاط المهمة')),actions:[FilledButton(onPressed:(){AppState.instance.updateLessonContent(l,x.text.trim());Navigator.pop(c);},child:const Text('حفظ'))]));}
}
